INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (73709,0,0,'Garrosh be concealin\' a whole hidden base. Where did his lust for power take him?',14,0,100.0,5,0,39146,76615,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (73709,3,0,'People be dyin\' up above. Da city is in chaos. I\'m gonna finish it - stop da bloodshed. I\'ll come back for ya.',14,0,100.0,1,0,0,76617,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (73710,3,0,'What should we do next?',14,0,100.0,6,0,0,76628,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (73714,3,0,'I\'ll offer what aid I can, $n. Just promise you\'ll make lots of delicious Kor\'kron corpses on your way to Garrosh.',12,0,100.0,1,0,0,76732,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (73715,3,0,'I\'ve got the brains, you\'ve got the muscle. Together, we\'ll make beautiful carnage.',12,0,100.0,396,0,0,76733,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (73775,0,0,'Iron Sentinels! To me!',14,1,100.0,0,0,0,77152,0,'LegionCore');
